/** Root-owned reader only; no active owner private key enters this client. */
import {serviceTestKeys} from './gradleOwnedServiceContract.js';
import {consumerPlan} from './gradleOwnedConsumerFixture.js';
import {SessionClient,SessionBootQuota} from '../../utils/gradleOwnedSessionRuntime.js';
import {ServiceContextFloor} from '../../utils/gradleOwnedServiceSession.js';
import {registryServiceAPIs,registryPurpose} from '../../utils/gradleOwnedRegistrySchema.js';
import {sourceAPIs,sourcePurpose} from '../../utils/gradleOwnedSourceSchema.js';
import {authorityOwnerAPIs,authorityOwnerPurpose} from '../../utils/gradleOwnedAuthorityOwnerSchema.js';
import {ConsumerServiceClient} from '../../utils/gradleOwnedConsumerClient.js';
import {ConsumerGraphBridge} from '../../utils/gradleOwnedConsumerBridge.js';
import {CurrentAuthorityVerifier} from '../../utils/gradleOwnedCurrentBridge.js';
import {readPlanCosts} from '../../utils/gradleOwnedReadPlan.js';
import {ownedSha256 as h} from '../../utils/gradleOwnedJson.js';
export const cgpNow=()=>Number(process.hrtime.bigint())/1e6;
export const cgpPhase=(api:string)=>api==='aux.ReadContext'?'context':api==='control.AcquireReadPin'?'pin':api==='control.ReadCurrentCheckpoint'?'checkpoint':['aux.ReadSourceDescriptor','aux.ReadSealedSource'].includes(api)?'source':api==='aux.PrepareAuthorityResult'?'authority':api==='aux.CompleteAuthorityResult'?'delivery-use':api==='aux.ReadAuthorityResult'?'result':api==='control.AcknowledgeDelivery'?'ack':api==='aux.FinishAuthorityResult'?'finish':'other';
export function cgpReader(f:any,data:any){const sessions=new Map<string,SessionClient>(),events:{api:string;phase:string;startMs:number;wallMs:number;outcome:string}[]=[],credential=f.f.registry.credentials.find((c:any)=>c.identity.credentialId==='reader-request'),quota=new SessionBootQuota(credential.identity),environment={now:()=>Math.floor(performance.now()),assertOpen(){},credentialCurrent:()=>true};
 for(const target of ['lineage-registry','provider','checkpoint-issuer','authority-broker']){const server=f.owners.get(target);let channel:string|undefined;const business=target==='lineage-registry'?{apis:registryServiceAPIs,purpose:registryPurpose}:target==='authority-broker'?{apis:authorityOwnerAPIs,purpose:authorityOwnerPurpose}:{apis:sourceAPIs,purpose:sourcePurpose};sessions.set(target,new SessionClient({registry:f.f.registry,pins:f.f.pins(),credentialId:credential.identity.credentialId,privateKey:serviceTestKeys['reader-request']!.privateKey,lineage:f.lineage,environment,business},target+'-reply',{async open(){channel=(await server.rpc('open',{credentialId:credential.identity.credentialId})).channel;},async exchange(packet){const r=await server.rpc('receive',{channel,packet:{wire:packet.wire.toString('base64'),...(packet.inner?{inner:packet.inner.toString('base64')}:{})}});return {wire:Buffer.from(r.wire,'base64'),...(r.inner?{inner:Buffer.from(r.inner,'base64')}:{})};},close(){if(channel&&server.child.connected)void server.rpc('close-channel',{channel}).catch(()=>{});channel=undefined;}},quota,new ServiceContextFloor(f.lineage)));}
 const client=new ConsumerServiceClient(sessions,f.lineage),call=client.call.bind(client);client.call=async(...args:Parameters<ConsumerServiceClient['call']>)=>{const startMs=cgpNow();let outcome='returned';try{return await call(...args);}catch(e){outcome='threw';throw e;}finally{events.push({api:args[0],phase:cgpPhase(args[0]),startMs,wallMs:cgpNow()-startMs,outcome});}};
 const plan=consumerPlan(),cost=readPlanCosts(plan),bridge=new ConsumerGraphBridge({client,registry:f.f.registry,providerInstance:'provider',verifier:new CurrentAuthorityVerifier(data.input.approvedBaseDigest,h(data.input.key)),scope:()=>data.request,plan,admission:()=>({remaining:Object.fromEntries(Object.keys(cost.edges).map(k=>[k,256])),frames:cost.frames,stages:cost.storageStages}),now:environment.now,sourceKey:data.input.key});return {bridge,events,client,sessions};
}
export function cgpCallSummary(profiles:any[],readerEvents:{phase:string;startMs:number;wallMs:number}[]){const groups:Record<string,{owner:string;api:string;phase:string;count:number;inclusiveWallMs:number;inclusiveCpuMs:number;maxWallMs:number}>={};for(const p of profiles){const phase=readerEvents.find(e=>p.startMs>=e.startMs&&p.startMs<e.startMs+e.wallMs)?.phase??'outside-reader-call';const key=p.role+'/'+p.api+'/'+phase,g=groups[key]??{owner:p.role,api:p.api,phase,count:0,inclusiveWallMs:0,inclusiveCpuMs:0,maxWallMs:0};g.count++;g.inclusiveWallMs+=p.wallMs;g.inclusiveCpuMs+=p.inclusiveCpuMs;g.maxWallMs=Math.max(g.maxWallMs,p.wallMs);groups[key]=g;}return {groups:Object.values(groups),note:'nested inclusive wall/CPU spans overlap; do not sum groups as read latency or owner total CPU'};}
